<template>
                  <div class="modal fade mymodal" id="boq-line-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">{{ budget.project }} , {{ budget.budget_name }} EXPECTED IPC VALUE</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-modal" ></button>
      </div>
<div class="modal-body" >
      <div class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <span v-if="loading" v-html="tableShimmer()"></span>
                    <div v-else class="custom-table table3">
<table class="table">
  <thead>
    <tr>
      <th scope="col">#</th>
      <th scope="col">BOQ Line</th>
      <th scope="col">Unit</th>
      <th scope="col">BOQ</th>
      <th scope="col">IPC</th>
      <th scope="col">Rate</th>
      <th scope="col">IPC Total</th>
    </tr>
  </thead>
  <tbody>
    <tr v-for="(line,index) in budget.boq_lines">
      <td>{{ index + 1 }}</td>
      <td>{{ line.name }}</td>
      <td>{{ line.unit }}</td>
      <!-- <td><input type="number" class="form-control" v-model="line.ipc_quantity" placeholder="Enter Rate" style="min-width: 220px;"></td> -->
      <td>{{ formatNumber(line.quantity) }}</td>
      <td>{{ formatNumber(line.ipc_quantity) }}</td>
      <td>{{ formatRate(line.rate) }}</td>
      <td>{{ formatRate(line.ipc_quantity * line.rate) }}</td>
    </tr>
    <tr>
      <td colspan="6"><strong>TOTAL COST</strong></td>
       <td>{{ formatRate(budget.total_cost) }}</td>
    </tr>
  </tbody>
</table>
                    </div>
                </div>
            </div>
        </div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-success btn-sm " @click="printBudget()" ><i class="bi bi-printer"></i></button>
         <button type="button" class="btn btn-danger btn-sm " data-bs-dismiss="modal">Close</button>
        <!-- <button type="button" class="btn btn-primary btn-sm py-2 px-2" @click="submitBudget()" >Submit</button> -->
      </div>


    </div>
  </div>

</div>


</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
     const route = useRoute();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const formatRate = inject('formatRate')
    const formatNumber = inject('formatNumber')
    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const budget = ref('')

const budget_id = ref(props.budgetId);

const getBudget = async () => {
    loading.value = true

    try {
        const response = await axiosInstance.get(
            `budget-approvals?budget_id=${budget_id.value}`
        )

        budget.value = response.data[0]
        budget.value.total_cost = (budget.value.boq_lines || []).reduce((total, line) => {
            return total + ((Number(line.ipc_quantity) || 0) * (Number(line.rate) || 0))
        }, 0)
    } catch(error) {
        console.log(error)
        showError(error.message)
    } finally {
        loading.value = false
    }
}


const printBudget = async () => {
  try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Budget Report</title>
<style>
  body {
    font-family: 'Courier New', monospace;
    margin: 40px;
    font-size: 13px;
  }

  .text-style {
    font-family: 'Courier New', monospace;
  }

  .company-title {
    text-align: center;
  }

  .title {
    text-align: center;
    font-size: 20px;
    margin: 10px 0;
    font-weight: bold;
  }

  .info-table {
    width: 100%;
    margin-top: 10px;
    margin-bottom: 15px;
    border-collapse: collapse;
  }

  .info-table td {
    border: none;
    padding: 3px;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
  }

  th,
  td {
    border: 0.5px solid #000;
    padding: 6px;
  }

  th {
    background: #f8f8f8;
    font-weight: bold;
  }

  .text-right {
    text-align: right;
  }

  .text-center {
    text-align: center;
  }

  hr {
    border: 0;
    border-top: 0.5px solid #000;
    margin: 0;
  }

  @media print {
    body {
      margin: 10mm;
    }
  }
</style>
</head>

<body>

<div class="company-title text-style">
<i>
<h1>COPEX CONTRACTORS CO. LTD</h1>
<div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
<div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
<div><b>Email:</b> info@copexcontractors.co.tz</div>
<div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
</i>
</div>

<hr style="margin-top:20px">

<div class="title">
BUDGET ESTIMATED IPC REPORT
</div>

<hr>

<table class="info-table">
<tr>
<td><b>Project</b></td>
<td>: ${budget.value.project}</td>

<td><b>Date</b></td>
<td>: ${new Date(budget.value.date).toLocaleDateString()}</td>
</tr>

<tr>
<td><b>Budget</b></td>
<td>: ${budget.value.budget_name}</td>

<td><b>Prepared By</b></td>
<td>: ${budget.value.issuer}</td>
</tr>

${
  budget.value.budget_description
    ? `
<tr>
<td><b>Description</b></td>
<td colspan="3">: ${budget.value.budget_description}</td>
</tr>
`
    : ""
}
</table>

<table>
<thead>
<tr>
<th style="width:5%">No.</th>
<th>Description</th>
<th style="width:10%">Unit</th>
<th style="width:12%">BOQ</th>
<th style="width:12%">IPC</th>
<th style="width:15%">Rate</th>
<th style="width:18%">Cost</th>
</tr>
</thead>

<tbody>

${budget.value.boq_lines
  .map(
    (item, index) => `
<tr>
<td class="text-center">${index + 1}</td>
<td>${item.name}</td>
<td class="text-center">${item.unit}</td>
<td class="text-right">${Number(item.quantity).toLocaleString()}</td>
<td class="text-right">${Number(item.ipc_quantity).toLocaleString()}</td>
<td class="text-right">${Number(item.rate).toLocaleString()}</td>
<td class="text-right">${Number(item.ipc_cost).toLocaleString()}</td>
</tr>
`
  )
  .join("")}

<tr>
<td colspan="6" class="text-right">
<strong>TOTAL IPC COST</strong>
</td>
<td class="text-right">
<strong>${Number(budget.value.total_ipc_cost).toLocaleString()}</strong>
</td>
</tr>

</tbody>
</table>


<hr style="margin-top:30px">

<table style="width:100%; border:none; margin-top:20px;">
    <tr>
        <td style="border:none; width:50%;">
            <strong>Printed By:</strong> ${JSON.parse(localStorage.getItem("user")).name || 'System User'}
        </td>
        <td style="border:none; text-align:right;">
            <strong>Date Printed:</strong> ${new Date().toLocaleString()}
        </td>
    </tr>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();

      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};




const props = defineProps({
    budgetId: String
});


watch(() => props.budgetId, (newId) => {
    if(newId){
        budget_id.value = newId
        getBudget()
    }
})



</script>